 if($type==='original'){if(access_is_viewer())throw new Exception('Original platform files are restricted to operational and audit roles.');$b=om_upload((int)($_GET['id']??0));$base=realpath(__DIR__.'/uploads');$file=realpath(__DIR__.'/'.($b['stored_path']??''));if(!$base||!$file||!str_starts_with(strtolower(str_replace('\\','/',$file)),strtolower(str_replace('\\','/',$base)).'/')||!is_file($file))throw new Exception('Original file unavailable.');header('Content-Type: application/vnd.openxmlformats-officedocument.spreadsheetml.sheet');header('Content-Disposition: attachment; filename="'.preg_replace('/[^A-Za-z0-9_.-]/','_',basename($b['filename'])).'"');readfile($file);exit;}
 if($type==='validation'){$b=om_upload((int)($_GET['id']??0));$plan=$b['status']==='Review'?om_plan($b):null;$heads=['Order ID','Status','Decision','Product Units','Validation'];$rows=[];if($plan){foreach($plan['orders'] as $r)$rows[]=[(string)$r['order'],$r['status'],$r['action'],array_sum($r['totals']),implode(' · ',$r['errors'])];}else{foreach(json_decode($b['result_json']??'{}',true)['validation']??[] as $r)$rows[]=[(string)$r['order'],$r['status'],$r['action'],array_sum($r['totals']),implode(' · ',$r['errors'])];foreach(om_query('SELECT e.*,o.order_no FROM om_events e LEFT JOIN om_orders o ON o.id=e.order_id WHERE upload_id=? ORDER BY e.id',[$b['id']]) as $r)$rows[]=[(string)($r['order_no']??''),'',$r['event_type'],'',$r['details_json']];}$r=['title'=>'Order Upload Validation #'.$b['id'],'headers'=>$heads,'rows'=>$rows];}
 elseif($type==='reservations')$r=om_reservation_report($_GET);
