 $meta=['Generated'=>date('Y-m-d H:i:s'),'User'=>current_user()['name'],'Filters'=>json_encode($_GET),'Note'=>'Reservations do not change physical stock. Statuses reflect confirmed uploads.'];if($format==='print'){report_print_document($r['title'],$r['headers'],$r['rows'],$meta);exit;}$tmp=tempnam(sys_get_temp_dir(),'om-export-');try{report_write_xlsx($tmp,$r['title'],$r['headers'],$r['rows'],$meta);header('Content-Type: application/vnd.openxmlformats-officedocument.spreadsheetml.sheet');header('Content-Disposition: attachment; filename="Order_Monitoring_'.date('Ymd_His').'.xlsx"');readfile($tmp);}finally{if(is_file($tmp))unlink($tmp);}exit;
