 elseif($a==='om_correct'){$id=(int)$_POST['upload_id'];om_correct($id,(int)$_POST['row_no'],(int)$_POST['revision'],$_POST);$url.='&upload_id='.$id;flash('Mapping saved. Review the new validation.','info');}
 elseif($a==='om_confirm'){$id=(int)$_POST['upload_id'];$result=om_confirm($id,$_POST['digest']??'',!empty($_POST['review_ack']));$url.='&upload_id='.$id;flash('Upload confirmed. '.implode(' · ',array_map(fn($k,$v)=>$k.': '.$v,array_keys($result),array_values($result))));}
 elseif($a==='om_cancel'){$id=(int)$_POST['upload_id'];$b=om_upload($id);om_owner($b);om_query("UPDATE om_uploads SET status='Cancelled' WHERE id=?",[$id]);om_event(null,$id,'Upload cancelled',['stock_changed'=>false]);$url.='&view='.($b['kind']==='Status'?'status':'register').'&platform='.rawurlencode($b['platform']);flash('Unposted upload cancelled. Correct the source file and validate again.');}
 elseif($a==='om_close'){om_close($_POST['platform']??'',$_POST['shop']??'',$_POST['fulfillment_date']??'');$url.='&platform='.rawurlencode($_POST['platform']).'&fulfillment_date='.rawurlencode($_POST['fulfillment_date']);flash('Registration closed. Reservations and physical balances are unchanged.');}
