 elseif($a==='om_aftersales'){om_aftersales((int)$_POST['order_id'],$_POST['outcome']??'',$_POST['reason']??'');$url.='&order_id='.(int)$_POST['order_id'];flash('Resolution saved. No stock changed.');}
 elseif($a==='om_reversal'){$id=(int)$_POST['order_id'];$o=om_order($id);if($o['platform_status']!=='Cancelled'||$o['posting']!=='Posted'||empty($_POST['warehouse_ack']))throw new Exception('Confirm the complete cancelled order never left the warehouse.');if(om_query('SELECT COUNT(*) FROM posted_returns WHERE platform=? AND original_ref=? AND reversed=0',[$o['platform'],$o['order_no']])->fetchColumn())throw new Exception('A physical return receipt already exists. Review it instead of reversing.');$batches=om_query('SELECT DISTINCT o.import_batch_id FROM om_postings p JOIN outflows o ON o.id=p.outflow_id WHERE p.order_id=? AND o.reversed_by_request IS NULL',[$id])->fetchAll(PDO::FETCH_COLUMN);if(count($batches)!==1||!$batches[0])throw new Exception('Historical order shares a legacy posting. Open Transaction Corrections and review its original batch; do not reverse unrelated orders.');$batch=(int)$batches[0];$others=(int)om_query("SELECT COUNT(*) FROM outflows WHERE import_batch_id=? AND order_id<>? AND reversed_by_request IS NULL",[$batch,$o['order_no']])->fetchColumn();if($others)throw new Exception('This legacy batch contains other orders. Use Transaction Corrections with a reviewed correction plan.');$req=reversal_request('Outflow',$batch,process_reason($_POST['reason']??''));om_event($id,null,'Linked reversal requested',['request_id'=>$req]);$url.='&order_id='.$id;flash('Linked reversal requested. A different Admin must approve; stock is unchanged until approval.');}
