 else throw new Exception('Unknown action.');
 }
}catch(Throwable $ex){flash(safe_error_message($ex),'danger');if(!empty($_POST['upload_id']))$url.='&upload_id='.(int)$_POST['upload_id'];elseif(!empty($_POST['order_id']))$url.='&order_id='.(int)$_POST['order_id'];if($_SERVER['REQUEST_METHOD']==='GET'){http_response_code(400);exit('<h1>Download unavailable</h1><p>'.e(safe_error_message($ex)).'</p>');}}
finally{if($lock)inventory_write_unlock($lock);}header('Location: '.$url);exit;
